    panel.innerHTML=`<button type="button" class="ai-back-results" data-ai-back>${t('← 전체 결과 보기','← All results')}</button><div class="ai-source-meta"><div><span>${t('이 사유의 근거가 된 원본','THE SOURCE BEHIND THIS REASON')}</span><strong>${t('합성 보험약관','Synthetic insurance policy')} <small>v${original.version}</small></strong></div><span class="ai-page-number">${x.page} / ${original.pageCount}</span></div><div class="ai-source-heading"><div><span class="ai-source-document">${x.packet} · ${t('시연용 약관','SYNTHETIC POLICY')}</span><h4>${x.short}</h4></div><button type="button" data-ai-page>${t('쪽 전체 보기','View full page')} ↗</button></div><div class="ai-source-crop" data-ai-crop aria-busy="true"><img src="${base+x.image}" alt="${t('합성 보험약관 원본의 '+x.page+'쪽 해당 조항 발췌','Clause excerpt from page '+x.page+' of the synthetic source PDF')}" decoding="async"/><div class="ai-highlight-layer" hidden>${marks(x.rectsCropPercent)}</div><p class="ai-image-status">${t('원본 위치를 불러오는 중…','Loading the source location…')}</p></div><div class="ai-verbatim"><span>${t('원본 PDF의 해당 문구','EXACT WORDING IN THE KOREAN PDF')}</span><blockquote lang="ko">${x.quote}</blockquote></div><div class="ai-source-actions"><div><span class="ai-location-dot"></span><span data-ai-status>${t('원본 확인 중','Checking the source')}</span></div><a data-ai-original href="${pdfUrl}#page=${x.page}" target="_blank" rel="noopener noreferrer">${t('원본 PDF 열기','Open source PDF')}<span aria-hidden="true">↗</span></a></div><details class="ai-source-record"><summary>${t('이 근거의 문서·버전·쪽수 보기','View the source document, version and page')}</summary><dl><div><dt>${t('업무 패킷','Packet')}</dt><dd>${x.packet} · ${t('가상 심사 기록','illustrative review')}</dd></div><div><dt>${t('문서','Document')}</dt><dd>INS-DEMO-POLICY-01 · v${original.version}</dd></div><div><dt>${t('위치','Location')}</dt><dd>${x.clause} · ${t('원본','source')} ${x.page}/${original.pageCount}</dd></div><div><dt>${t('원본 파일','Source file')}</dt><dd>${original.pdf}<small>SHA-256 ${original.pdfSha256.slice(0,16)}…</small></dd></div></dl></details>`;
    const img=panel.querySelector('img'),layer=panel.querySelector('.ai-highlight-layer'),crop=panel.querySelector('[data-ai-crop]'),status=panel.querySelector('[data-ai-status]'),link=panel.querySelector('[data-ai-original]');
    function finish(ok){if(token!==epoch||img!==panel.querySelector('img'))return;panel.setAttribute('aria-busy','false');crop.setAttribute('aria-busy','false');if(ok){layer.hidden=false;crop.querySelector('.ai-image-status').hidden=true;status.textContent=t('원본 위치 확인 · '+x.page+'쪽','Source location confirmed · page '+x.page);link.removeAttribute('aria-disabled');}else{img.hidden=true;layer.hidden=true;crop.classList.add('ai-source-error');crop.querySelector('.ai-image-status').textContent=t('원본 페이지를 불러오지 못했습니다. 사유를 다시 선택해 확인해 주세요.','The source page could not be loaded. Select the item again to reload its source.');status.textContent=t('원본 확인 필요','Source needs checking');link.removeAttribute('href');link.setAttribute('aria-disabled','true');}}
    img.addEventListener('load',()=>finish(img.naturalWidth>0),{once:true});img.addEventListener('error',()=>finish(false),{once:true});if(img.complete)queueMicrotask(()=>finish(img.naturalWidth>0));
